import { Skeleton, Image } from "antd";
import React from "react";

function ShimmerImage(props) {
  return props.src ? (
    <Image
      {...props}
      placeholder={
        <Image
          preview={false}
          alt="img"
          className="w-100"
          width={props.width}
          height={props.height}
          src="data:image/jpeg;base64,"
        />
      }
      alt="img"
    />
  ) : (
    <Skeleton.Image className="w-100" />
  );
}

export default ShimmerImage;
